package server

const adminHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>NekoSune Radio | Control Center</title><style>
:root{color-scheme:dark;--bg:#080f0c;--panel:#112019;--soft:#13271d;--edge:#2b4b39;--accent:#78efac;--muted:#9db6a8;--white:#f2fff6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--white);font:14px/1.6 system-ui,"Segoe UI",sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #39654d;background:#214934;color:var(--white);padding:10px 15px;border-radius:9px;font-weight:650}button:hover{background:#306649}button:disabled{opacity:.55;cursor:not-allowed}.secondary{background:transparent}.danger{border-color:#814b50;background:#492027;color:#ffe9e9}input{background:#0b1a12;border:1px solid var(--edge);padding:12px;border-radius:9px;color:white;width:100%;min-width:0}input[type=file]{max-width:330px}.layout{display:grid;grid-template-columns:248px 1fr;min-height:100vh}.sidebar{background:#0c1811;border-right:1px solid var(--edge);padding:25px 15px;position:sticky;top:0;height:100vh;overflow:auto}.brand{font-size:20px;font-weight:850;padding:4px 13px 25px}.brand em{color:var(--accent);font-style:normal}.small{font-size:11px;color:var(--muted);letter-spacing:1.5px;font-weight:750;margin:23px 12px 10px}.nav{display:block;width:100%;border:0;background:transparent;color:var(--muted);text-align:left;padding:12px 15px;margin:3px 0;border-radius:10px}.nav:hover,.nav.active{color:var(--accent);background:#193527}.side-bottom{margin:30px 12px}.side-bottom a{color:var(--muted);text-decoration:none}.work{padding:32px clamp(18px,4vw,58px) 80px;max-width:1540px;width:100%;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;padding-bottom:24px;border-bottom:1px solid var(--edge)}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:2.6px}.top h1{margin:5px 0;font-size:clamp(28px,3vw,39px);letter-spacing:-1px}.muted{color:var(--muted)}.overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:23px 0}.tile,.panel{background:linear-gradient(145deg,#15291e,#101d16);border:1px solid var(--edge);border-radius:14px;padding:22px}.tile strong{font-size:32px;display:block;color:var(--accent)}.tile small{font-size:11px;letter-spacing:1.2px;color:var(--muted)}.section{display:none}.section.active{display:block}.row{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:17px 0;border-bottom:1px solid var(--edge)}.row .grow{flex:1;min-width:180px}.row small{display:block;color:var(--muted)}.pill{color:var(--accent);font-size:12px}.station-title{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}.toolbar select{color:white;background:#102418;padding:11px;border:1px solid var(--edge);border-radius:9px}.notice{padding:15px 0;min-height:46px;color:var(--accent)}table{width:100%;border-collapse:collapse}td,th{text-align:left;border-bottom:1px solid var(--edge);padding:14px 10px}th{font-size:11px;color:var(--muted);letter-spacing:1px;text-transform:uppercase}.wrap{overflow:auto}.login{max-width:530px;margin:12vh auto}.empty{color:var(--muted);padding:20px 0}.hidden{display:none!important}.help{font-size:12px;color:var(--muted)}@media(max-width:850px){.layout{grid-template-columns:1fr}.sidebar{position:relative;height:auto;display:flex;align-items:center;flex-wrap:wrap;padding:10px}.brand{padding:10px}.small{display:none}.nav{width:auto}.side-bottom{margin:5px}.work{padding:20px}.overview{grid-template-columns:1fr 1fr}.overview .tile:last-child{grid-column:span 2}}@media(max-width:540px){.top{display:block}td,th{padding:9px 5px}.row .grow{min-width:100%}}</style></head><body><div class="layout">
<aside class="sidebar"><div class="brand">Neko<em>Sune</em> <span style="font-size:12px;font-weight:400">Radio</span></div><div class="small">CONTROL CENTER</div><button class="nav active" data-page="overview">Overview</button><button class="nav" data-page="stations">Radio stations</button><button class="nav" data-page="library">Music library</button><button class="nav" data-page="listeners">Live listeners</button><button class="nav" data-page="bans">IP moderation</button><div class="side-bottom"><a href="/">← Public radio</a><br><a href="/docs">API docs</a></div></aside>
<main class="work"><header class="top"><div><div class="eyebrow">PRIVATE CONTROL CENTER</div><h1 id="page-title">Radio overview</h1><div class="muted" id="subtitle">Manage all broadcasting channels from one place.</div></div><button id="signout" class="secondary hidden">Sign out</button></header>
<section id="login" class="login panel"><h2>Administrator sign in</h2><p class="muted">Enter the password configured under [admin] in config.toml.</p><form id="login-form"><input id="password" type="password" required autocomplete="current-password" placeholder="Admin password"><p><button type="submit">Sign in</button></p></form></section>
<div id="authenticated" class="hidden">
<section class="section active" data-view="overview"><div class="overview"><div class="tile"><strong id="metric-stations">0</strong><small>RADIO STATIONS</small></div><div class="tile"><strong id="metric-listeners">0</strong><small>LISTENING NOW</small></div><div class="tile"><strong id="metric-online">0</strong><small>ONLINE CHANNELS</small></div></div><div class="panel"><h2>Station activity</h2><div id="overview-stations"></div></div></section>
<section class="section" data-view="stations"><div class="panel"><div class="station-title"><h2>Your radio stations</h2><span class="muted">Station controls</span></div><div id="station-list"></div><p class="help">Stopping a station currently closes new listener access only. Creating or permanently removing station instances is not yet supported by the live server runtime; edit your config.toml and restart to add/remove a station.</p></div></section>
<section class="section" data-view="library"><div class="panel"><div class="station-title"><h2>Music library</h2><span class="pill">LIVE ROTATION</span></div><div class="toolbar"><label for="station-select">Station</label><select id="station-select"></select><button class="secondary" id="refresh-library">Refresh</button></div><form id="upload-form" class="toolbar"><input id="upload-file" type="file" accept=".mp3,.flac,.wav,.ogg,.opus,.aac,.m4a,.webm,.wma" required><button id="upload-button" type="submit">Upload music</button></form><p class="help">New music enters the upcoming rotation immediately without restarting the station. Removing a song excludes it from future turns; currently playing audio is not intentionally interrupted. The final track cannot be deleted.</p><div id="library-summary" class="muted"></div><div class="wrap"><table><thead><tr><th>Song</th><th>Artist</th><th>Filename</th><th></th></tr></thead><tbody id="library-tracks"></tbody></table></div></div></section>
<section class="section" data-view="listeners"><div class="panel"><div class="station-title"><h2>Connected listeners</h2><button class="secondary" id="refresh-listeners">Refresh</button></div><p class="help">Private IP information, available only to administrators.</p><div id="listeners-list"></div></div></section>
<section class="section" data-view="bans"><div class="panel"><h2>IP moderation</h2><form id="ban-form" class="toolbar"><input id="ban-ip" placeholder="IPv4 or IPv6 address" required style="max-width:300px"><button type="submit">Ban IP</button></form><div id="bans-list"></div></div></section>
</div><div id="notice" class="notice" aria-live="polite"></div></main></div>
<script>
const $=id=>document.getElementById(id);let password=sessionStorage.getItem("radio_admin")||"",stations=[],chosen="",currentPage="overview";
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function message(text){$("notice").textContent=text}
async function api(path,init={}){init.headers={...init.headers,Authorization:"Bearer "+password};const r=await fetch(path,init);if(!r.ok)throw Error((await r.text()).slice(0,180));return r.json()}
function page(name){currentPage=name;document.querySelectorAll(".nav").forEach(n=>n.classList.toggle("active",n.dataset.page===name));document.querySelectorAll(".section").forEach(n=>n.classList.toggle("active",n.dataset.view===name));$("page-title").textContent=({overview:"Radio overview",stations:"Radio stations",library:"Music library",listeners:"Live listeners",bans:"IP moderation"})[name];if(name==="library")loadLibrary();if(name==="listeners")loadListeners();if(name==="bans")loadBans()}
document.querySelectorAll(".nav").forEach(n=>n.onclick=()=>page(n.dataset.page));
function stationRow(st,overview=false){const row=node("div",undefined,"row"),heading=node("div",undefined,"grow");heading.append(node("b",st.name),node("small",st.id+" · "+st.listeners+" connections · "+(st.online?"On air":"Offline")));row.append(heading);const listen=node("button","Manage music","secondary");listen.onclick=()=>{chosen=st.id;$("station-select").value=chosen;page("library")};row.append(listen);if(!overview){const toggle=node("button",st.online?"Stop station":"Start station");toggle.onclick=async()=>{try{await api("/api/admin/stations/"+encodeURIComponent(st.id)+"/state",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({online:!st.online})});await loadStations();message(st.name+" updated")}catch(e){message(e.message)}};row.append(toggle)}return row}
async function loadStations(){stations=await api("/api/admin/stations");$("login").classList.add("hidden");$("authenticated").classList.remove("hidden");$("signout").classList.remove("hidden");$("metric-stations").textContent=stations.length;$("metric-listeners").textContent=stations.reduce((n,s)=>n+s.listeners,0);$("metric-online").textContent=stations.filter(s=>s.online).length;for(const [id,overview]of [["overview-stations",true],["station-list",false]]){const root=$(id);root.replaceChildren();stations.forEach(st=>root.append(stationRow(st,overview)))}const select=$("station-select");select.replaceChildren();stations.forEach(st=>{const o=new Option(st.name,st.id);select.add(o)});if(!stations.some(s=>s.id===chosen))chosen=stations[0]?.id||"";select.value=chosen;}
async function loadLibrary(){if(!chosen)return;try{const d=await api("/api/admin/stations/"+encodeURIComponent(chosen)+"/library");const tbody=$("library-tracks");tbody.replaceChildren();$("library-summary").textContent=(d.tracks||[]).length+" tracks available";for(const track of d.tracks||[]){const row=node("tr");for(const value of [track.title||track.filename,track.artist||"—",track.filename]){const cell=node("td",value);row.append(cell)}const td=node("td");const del=node("button","Delete","danger");del.onclick=async()=>{if(!confirm("Delete "+track.filename+" permanently?"))return;try{await api("/api/admin/stations/"+encodeURIComponent(chosen)+"/library",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify({filename:track.filename})});message("Deleted "+track.filename);await loadLibrary();await loadStations()}catch(e){message(e.message)}};td.append(del);row.append(td);tbody.append(row)}}catch(e){message("Cannot load library: "+e.message)}}
$("station-select").onchange=e=>{chosen=e.target.value;loadLibrary()};$("refresh-library").onclick=loadLibrary;
$("upload-form").onsubmit=async e=>{e.preventDefault();if(!chosen||!$("upload-file").files.length)return;const button=$("upload-button"),body=new FormData();body.append("file",$("upload-file").files[0]);button.disabled=true;message("Uploading music…");try{const r=await api("/api/admin/stations/"+encodeURIComponent(chosen)+"/upload",{method:"POST",body});message(r.message);$("upload-file").value="";await loadLibrary();await loadStations()}catch(err){message(err.message)}finally{button.disabled=false}};
async function setBan(ip,banned){try{await api("/api/admin/bans",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ip,banned})});message((banned?"Banned ":"Unbanned ")+ip);if(currentPage==="bans")await loadBans();else await loadListeners()}catch(e){message(e.message)}}
async function loadListeners(){try{const data=await api("/api/admin/listeners"),root=$("listeners-list");root.replaceChildren();for(const [station,people]of Object.entries(data.stations||{})){root.append(node("h3",station+" · "+people.length+" connected"));for(const user of people){const row=node("div",undefined,"row");row.append(node("span",user.ip,"grow"),node("span",(user.country||"Unknown country")+" · "+user.duration_seconds+" seconds","muted"));const b=node("button","Ban IP","secondary");b.onclick=()=>setBan(user.ip,true);row.append(b);root.append(row)}}}catch(e){message(e.message)}}
$("refresh-listeners").onclick=loadListeners;
async function loadBans(){try{const data=await api("/api/admin/bans"),root=$("bans-list");root.replaceChildren();for(const ip of data.banned_ips||[]){const row=node("div",undefined,"row");row.append(node("strong",ip,"grow"));const b=node("button","Unban","secondary");b.onclick=()=>setBan(ip,false);row.append(b);root.append(row)}if(!(data.banned_ips||[]).length)root.append(node("p","No banned IP addresses.","empty"))}catch(e){message(e.message)}}
$("ban-form").onsubmit=e=>{e.preventDefault();const ip=$("ban-ip").value.trim();if(ip)setBan(ip,true)};
$("login-form").onsubmit=e=>{e.preventDefault();password=$("password").value;sessionStorage.setItem("radio_admin",password);loadStations().catch(err=>message("Login failed: "+err.message))};
$("signout").onclick=()=>{password="";sessionStorage.removeItem("radio_admin");$("login").classList.remove("hidden");$("authenticated").classList.add("hidden");$("signout").classList.add("hidden");message("")};
if(password)loadStations().catch(err=>message("Session expired or invalid password: "+err.message));
setInterval(()=>{if(!password)return;if(currentPage==="overview"||currentPage==="stations")loadStations().catch(()=>{});if(currentPage==="listeners")loadListeners();},15000);
</script></body></html>`
